/**
 * Use balance_amount, credit_amount and gateway_amount, which also show a refund split between destinations.
 * @deprecated
 */
export type RefundDestination = (typeof RefundDestination)[keyof typeof RefundDestination];

export const RefundDestination = {
  balance: "balance",
  gateway: "gateway",
} as const;

/**
 * Summary of the parts in `transactions`.
 *
 * - `pending`: nothing has been returned yet, and at least one part is in progress.
 * - `processing`: some parts have been returned, and at least one is still in progress.
 * - `succeeded`: every part has been returned.
 * - `failed`: no part is in progress and at least one has failed. What was returned is in
 *   settled_amount.
 *
 * Returns to the balance and to credit grants complete shortly after the refund is made; a
 * return to a payment method completes when the gateway confirms it.
 */
export type RefundStatus = (typeof RefundStatus)[keyof typeof RefundStatus];

export const RefundStatus = {
  pending: "pending",
  processing: "processing",
  succeeded: "succeeded",
  failed: "failed",
} as const;

/**
 * Why the refund was made. New codes may be added; treat an unknown code as unspecified.
 *
 * - `provisioning_failed`: the purchase could not be delivered.
 * - `order_expired`: the order expired after part of it was paid.
 * - `order_canceled`: the order was canceled after part of it was paid.
 * - `change_canceled`: a scheduled change was withdrawn after part of it was paid.
 * - `change_expired`: a scheduled change could not take effect in time.
 * - `subscription_canceled`: the unused value of a canceled subscription, under its refund terms.
 * - `future_period_canceled`: a renewal that had not started was withdrawn.
 * - `downgrade_difference`: after a downgrade, the remaining paid value, valued under each paid period's refund
 *   policy and as `prorated` where that policy is `none`, minus the new configuration's value for the remaining
 *   time: each whole month at the change item's `monthly_list_amount` and the remainder in proportion to the
 *   length of the month it falls in, or without `monthly_list_amount`, the new period price in proportion to the
 *   remaining time.
 * - `usage_true_up`: usage priced over the whole month cost less than was charged.
 * - `payment_not_applied`: a payment arrived after its invoice could no longer be paid.
 * - `operator`: made by the platform operator.
 */
export type RefundReason = (typeof RefundReason)[keyof typeof RefundReason];

export const RefundReason = {
  provisioning_failed: "provisioning_failed",
  order_expired: "order_expired",
  order_canceled: "order_canceled",
  change_canceled: "change_canceled",
  change_expired: "change_expired",
  subscription_canceled: "subscription_canceled",
  future_period_canceled: "future_period_canceled",
  downgrade_difference: "downgrade_difference",
  usage_true_up: "usage_true_up",
  payment_not_applied: "payment_not_applied",
  operator: "operator",
} as const;

export interface Refund {
  transaction_id?: string;
  cancellation_item_id?: string;
  /** The refund split by original payment source, with each result. Unknown gateway results stay pending. */
  transactions: Transaction[];
  id: string;
  billing_account_id?: number;
  /** @nullable */
  invoice_id?: string | null;
  /**
   * The order the refund belongs to: the order that caused it, such as a downgrade, otherwise the order of the refunded invoice. Null for refunds of top-ups and usage invoices.
   * @nullable
   */
  order_id?: string | null;
  /** The whole refund. Equals balance_amount plus credit_amount plus gateway_amount. */
  amount: Money;
  /** The part returned to the account balance. */
  balance_amount: Money;
  /** The part restored to the credit grants that paid for it. */
  credit_amount: Money;
  /** The part returned to the payment method it was paid with. */
  gateway_amount: Money;
  /** What has actually been returned. */
  settled_amount?: Money;
  currency: string;
  /**
   * Use balance_amount, credit_amount and gateway_amount, which also show a refund split between destinations.
   * @deprecated
   */
  destination?: RefundDestination;
  /**
   * Summary of the parts in `transactions`.
   *
   * - `pending`: nothing has been returned yet, and at least one part is in progress.
   * - `processing`: some parts have been returned, and at least one is still in progress.
   * - `succeeded`: every part has been returned.
   * - `failed`: no part is in progress and at least one has failed. What was returned is in
   *   settled_amount.
   *
   * Returns to the balance and to credit grants complete shortly after the refund is made; a
   * return to a payment method completes when the gateway confirms it.
   */
  status: RefundStatus;
  /** When the last part was returned. Present with `succeeded`. */
  settled_at?: string;
  reason: RefundReason;
  created_at: string;
}

